    marker = min((v for v in counts if v != background), key=lambda v: counts[v])
    out = [row[:] for row in grid]

    # Convert background cells between consecutive marker cells in any row/column.
    for r in range(h):
        positions = [c for c, value in enumerate(grid[r]) if value == marker]
        for a, b in zip(positions, positions[1:]):
            if all(grid[r][c] == background for c in range(a + 1, b)):
                for c in range(a + 1, b):
                    out[r][c] = 3

